import{_ as r,a as i,b as o,c as l,d as s}from"./chunks/wiring_diagram.DlPpBkTe.js";import{_ as n,C as c,o as d,c as h,j as t,a as p,E as u,al as m}from"./chunks/framework.7vp1BMOE.js";const v=JSON.parse('{"title":"MicoAir743-Lite","description":"","frontmatter":{},"headers":[],"relativePath":"ko/flight_controller/micoair743-lite.md","filePath":"ko/flight_controller/micoair743-lite.md"}'),f={name:"ko/flight_controller/micoair743-lite.md"};function g(b,e,_,k,S,A){const a=c("Badge");return d(),h("div",null,[e[0]||(e[0]=t("h1",{id:"micoair743-lite",tabindex:"-1"},[p("MicoAir743-Lite "),t("a",{class:"header-anchor",href:"#micoair743-lite","aria-label":'Permalink to "MicoAir743-Lite"'},"​")],-1)),u(a,{type:"tip",text:"PX4 v1.17"}),e[1]||(e[1]=m('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://micoair.com/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>MicoAir743-Lite is an ultra-high performance H743 flight controller with an unbeatable price, featuring the ICM45686 IMU sensor and integrated Bluetooth telemetry.</p><p><img src="'+r+'" alt="MicoAir743-Lite Front View"></p><p>Equipped with a high-performance H7 processor, the MicoAir743-Lite features a compact form factor with SH1.0 connectors (which are more suitable than Pixhawk-standard GH1.25 for this board size). When paired with Bluetooth telemetry, the board can be debugged with a phone or PC.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="micoair743-lite-v1-1" tabindex="-1">MicoAir743-Lite (v1.1) <a class="header-anchor" href="#micoair743-lite-v1-1" aria-label="Permalink to &quot;MicoAir743-Lite (v1.1)&quot;">​</a></h2><p><img src="'+i+'" alt="MicoAir743-Lite Back View"></p><h2 id="요약" tabindex="-1">요약 <a class="header-anchor" href="#요약" aria-label="Permalink to &quot;요약&quot;">​</a></h2><h3 id="processors-sensors" tabindex="-1">Processors &amp; Sensors <a class="header-anchor" href="#processors-sensors" aria-label="Permalink to &quot;Processors &amp; Sensors&quot;">​</a></h3><ul><li>FMU Processor: STM32H743 <ul><li>32 Bit Arm® Cortex®-M7, 480MHz, 2MB flash memory, 1MB RAM</li></ul></li><li>내장 센서 : <ul><li>Accel/Gyro: ICM-45686 (with BalancedGyro™ Technology)</li><li>Barometer: SPA06</li></ul></li><li>On-board Bluetooth Telemetry <ul><li>Connected to UART8 internally, baudrate 115200</li><li>Connecting to QGC (PC or Android phone) via Bluetooth</li></ul></li><li>기타 특성: <ul><li>Operating &amp; storage temperature: -20 ~ 85°c</li></ul></li></ul><h3 id="인터페이스" tabindex="-1">인터페이스 <a class="header-anchor" href="#인터페이스" aria-label="Permalink to &quot;인터페이스&quot;">​</a></h3><ul><li>8 UART (TELEM / GPS / RC)</li><li>14 PWM outputs （10 supports DShot）</li><li>Support multiple RC inputs (SBUS / CRSF / DSM)</li><li>1 GPS port</li><li>1 I2C port</li><li>2 ADC port2 (VBAT, Current)</li><li>1 DJI O3/O4 VTX connector</li><li>1 MicroSD Card Slot</li><li>1 USB Type-C</li></ul><h3 id="electrical-data" tabindex="-1">Electrical data <a class="header-anchor" href="#electrical-data" aria-label="Permalink to &quot;Electrical data&quot;">​</a></h3><ul><li>VBAT Input: <ul><li>2~6S (6~27V)</li></ul></li><li>USB Power Input: <ul><li>4.75~5.25V</li></ul></li><li>BEC Output: <ul><li>5V 2A (for controller, receiver, GPS, optical flow or other devices)</li><li>9V 2A (for video transmitter, camera)</li></ul></li></ul><h3 id="mechanical-data" tabindex="-1">Mechanical data <a class="header-anchor" href="#mechanical-data" aria-label="Permalink to &quot;Mechanical data&quot;">​</a></h3><ul><li>Mounting: 30.5 x 30.5mm, Φ4mm</li><li>Dimensions: 36 x 36 x 8 mm</li><li>Weight: 10g</li></ul><p><img src="'+o+'" alt="MicoAir743-Lite Size"></p><h2 id="store" tabindex="-1">Where to Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where to Buy {#store}&quot;">​</a></h2><p>Order from <a href="https://store.micoair.com/product/micoair743-lite/" target="_blank" rel="noreferrer">MicoAir Tech Store</a>.</p><h2 id="핀배열" tabindex="-1">핀배열 <a class="header-anchor" href="#핀배열" aria-label="Permalink to &quot;핀배열&quot;">​</a></h2><p>Pinouts definition can be found in the <a href="https://raw.githubusercontent.com/PX4/PX4-Autopilot/refs/heads/main/docs/assets/flight_controller/micoair743_lite/micoair743_lite_pinout.xlsx" target="_blank" rel="noreferrer">MicoAir743-Lite_pinout.xlsx</a> file.</p><h2 id="시리얼-포트-매핑" tabindex="-1">시리얼 포트 매핑 <a class="header-anchor" href="#시리얼-포트-매핑" aria-label="Permalink to &quot;시리얼 포트 매핑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>장치</th><th>포트</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>TELEM1</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>GPS2</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>GPS1</td></tr><tr><td>UART4</td><td>/dev/ttyS3</td><td>TELEM2</td></tr><tr><td>UART5</td><td>/dev/ttyS4</td><td>TELEM3</td></tr><tr><td>USART6</td><td>/dev/ttyS5</td><td>RC</td></tr><tr><td>UART7</td><td>/dev/ttyS6</td><td>UART6</td></tr><tr><td>UART8</td><td>/dev/ttyS7</td><td>TELEM4</td></tr></tbody></table><h2 id="interfaces-diagram" tabindex="-1">Interfaces Diagram <a class="header-anchor" href="#interfaces-diagram" aria-label="Permalink to &quot;Interfaces Diagram&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>All the connectors used on the board are SH1.0</p></div><p><img src="'+l+'" alt="MicoAir743-Lite Interface Diagram"></p><h2 id="sample-wiring-diagram" tabindex="-1">Sample Wiring Diagram <a class="header-anchor" href="#sample-wiring-diagram" aria-label="Permalink to &quot;Sample Wiring Diagram&quot;">​</a></h2><p><img src="'+s+'" alt="MicoAir743-Lite Wiring Diagram"></p><h2 id="펌웨어-빌드" tabindex="-1">펌웨어 빌드 <a class="header-anchor" href="#펌웨어-빌드" aria-label="Permalink to &quot;펌웨어 빌드&quot;">​</a></h2><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> micoair_h743-lite_default</span></span></code></pre></div><h2 id="펌웨어-설치" tabindex="-1">펌웨어 설치 <a class="header-anchor" href="#펌웨어-설치" aria-label="Permalink to &quot;펌웨어 설치&quot;">​</a></h2><p>펌웨어는 일반적인 방법으로 설치할 수 있습니다.</p><ul><li><p>소스 빌드 및 업로드</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> micoair_h743-lite_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div></li><li><p><a href="./../config/firmware">Load the firmware</a> using <em>QGroundControl</em>. 미리 빌드된 펌웨어나 사용자 지정 펌웨어를 사용할 수 있습니다.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>At time of writing the only pre-built software is <code>PX4 main</code> (see <a href="./../config/firmware#installing-px4-main-beta-or-custom-firmware">Installing PX4 Main, Beta or Custom Firmware</a>). Release builds will be supported for PX4 v1.17 and later.</p></div></li></ul><p>:::</p><h2 id="무선-조종" tabindex="-1">무선 조종 <a class="header-anchor" href="#무선-조종" aria-label="Permalink to &quot;무선 조종&quot;">​</a></h2><p>A <a href="./../getting_started/rc_transmitter_receiver">Radio Control (RC) system</a> is required if you want to manually control your vehicle (PX4 does not require a radio system for autonomous flight modes).</p><p>The RC port is connected to the FMU and you can attach a receiver that uses the protocols <code>DSM</code>, <code>SBUS</code>, <code>CSRF</code>, <code>GHST</code>, or other protocol listed in <a href="./../modules/modules_driver_radio_control">Radio Control modules</a>. You will need to enable the protocol by setting the corresponding parameter <code>RC_xxxx_PRT_CFG</code>, such as <a href="./../advanced_config/parameter_reference#RC_CRSF_PRT_CFG">RC_CRSF_PRT_CFG</a> for a <a href="./../telemetry/crsf_telemetry">CRSF receiver</a>.</p><h2 id="지원-플랫폼-및-기체" tabindex="-1">지원 플랫폼 및 기체 <a class="header-anchor" href="#지원-플랫폼-및-기체" aria-label="Permalink to &quot;지원 플랫폼 및 기체&quot;">​</a></h2><p>일반 RC 서보 또는 Futaba S-Bus 서보로 제어 가능한 모든 멀티콥터/비행기/로버 또는 보트. The complete set of supported configurations can be seen in the <a href="./../airframes/airframe_reference">Airframes Reference</a>.</p><h2 id="주변-장치" tabindex="-1">주변 장치 <a class="header-anchor" href="#주변-장치" aria-label="Permalink to &quot;주변 장치&quot;">​</a></h2><ul><li><a href="https://micoair.com/radio_telemetry/" target="_blank" rel="noreferrer">MicoAir Telemetry Radio Modules</a></li><li><a href="https://micoair.com/optical_range_sensor/" target="_blank" rel="noreferrer">MicoAir Optical &amp; Range Sensor</a></li><li><a href="https://micoair.com/gps/" target="_blank" rel="noreferrer">MicoAir GPS</a></li><li><a href="https://micoair.com/esc/" target="_blank" rel="noreferrer">MicoAir ESC Modules</a></li></ul><h2 id="추가-정보" tabindex="-1">추가 정보 <a class="header-anchor" href="#추가-정보" aria-label="Permalink to &quot;추가 정보&quot;">​</a></h2><ul><li><a href="https://micoair.com/" target="_blank" rel="noreferrer">MicoAir Tech.</a></li><li><a href="https://micoair.com/flightcontroller_micoair743lite/" target="_blank" rel="noreferrer">Details about MicoAir743-Lite</a></li><li><a href="https://docs.qgroundcontrol.com/Stable_V5.0/en/qgc-user-guide/getting_started/download_and_install.html" target="_blank" rel="noreferrer">QGroundControl Download and Install</a></li></ul>',44))])}const M=n(f,[["render",g]]);export{v as __pageData,M as default};
